// Merge the WAF alert with the AbuseIPDB lookup and build the Slack messages.
// Everything in the alert is attacker-controlled (payloads, paths, even the
// host header), so it is escaped: unescaped, a payload containing <!channel>
// would ping the whole channel, and <url|text> would render a disguised link.
const alert = $('WAF alert webhook').first().json.body ?? {};
const lookup = $input.first().json ?? {};
const intel = lookup.data ?? null; // AbuseIPDB "data" object; absent when the lookup failed

const RED = '#d40e0d';   // blocked
const AMBER = '#e8a317'; // detected in monitor mode (not blocked)
// Slack caps a button's value at 2000 characters; an over-long value would
// make Slack reject the whole message, so such values get no button.
const SLACK_BUTTON_VALUE_MAX = 2000;

const esc = (value, max = 300) => String(value ?? '')
  .slice(0, max)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/`/g, "'"); // a backtick in a payload would close the code block

const pct = (p) => (typeof p === 'number' ? `${(p * 100).toFixed(1)}%` : 'n/a');
const section = (text) => ({ type: 'section', text: { type: 'mrkdwn', text } });

const values = Array.isArray(alert.blocked_values) ? alert.blocked_values : [];
// "regex": a WAF signature matched (no ML score); "ml": the model's score crossed the threshold.
const byRegex = alert.source_engine === 'regex';
const signatureId = esc(alert.signature?.id ?? 'unknown', 60);
// -1 = unknown, so the threat check routes failed lookups to the standard channel.
const abuseScore = typeof intel?.abuseConfidenceScore === 'number' ? intel.abuseConfidenceScore : -1;
const lookupError = typeof lookup.error === 'string' ? lookup.error : lookup.error?.message;
const osint = intel
  ? [
      `*AbuseIPDB:* ${abuseScore}% abuse confidence, ${intel.totalReports ?? 0} reports from ${intel.numDistinctUsers ?? 0} users (last: ${esc(intel.lastReportedAt ?? 'never', 40)})`,
      `*ISP:* ${esc(intel.isp, 100)} | *Usage:* ${esc(intel.usageType, 60)} | *Domain:* ${esc(intel.domain, 100)}`,
      `*Country:* ${esc(intel.countryCode, 4)} | *Tor:* ${intel.isTor ? 'yes' : 'no'} | *Public IP:* ${intel.isPublic ? 'yes' : 'no'}`,
    ].join('\n')
  : `_AbuseIPDB lookup failed: ${esc(lookupError ?? 'no data', 200)}_`;

// One section per flagged value, each with its own "Flag as false positive"
// button. The button value carries the original (unescaped) string, its
// source and the WAF request_id to the feedback workflow (n8n_feedback_loop.json).
function valueBlock(v, index) {
  const why = byRegex ? `signature \`${esc(v.signature ?? alert.signature?.id, 60)}\`` : pct(v.probability);
  const block = section(
    `*${esc(v.source, 80)}* (${why})\n\`\`\`${esc(v.value ?? '[value not included]', 1000)}\`\`\``,
  );
  // No button for signature hits: training data only changes the model, not
  // the signature that blocked the value.
  if (byRegex || typeof v.value !== 'string' || !v.value.trim()) return block;
  const buttonValue = JSON.stringify({ v: 1, q: v.value, s: v.source ?? '', r: alert.request_id ?? '' });
  if (buttonValue.length > SLACK_BUTTON_VALUE_MAX) return block;
  block.accessory = {
    type: 'button',
    action_id: `waf_fp_${index}`,
    text: { type: 'plain_text', text: 'Flag as false positive' },
    value: buttonValue,
    confirm: {
      title: { type: 'plain_text', text: 'Mark this value as safe?' },
      text: {
        type: 'mrkdwn',
        text: `The *${esc(v.source, 80)}* value will be added to the training data as safe (label 0). Only confirm legitimate traffic: marking a real attack safe teaches the model to let it through.`,
      },
      confirm: { type: 'plain_text', text: 'Mark safe' },
      deny: { type: 'plain_text', text: 'Cancel' },
    },
  };
  return block;
}

const blocked = alert.action === 'block';
const outcome = blocked ? 'blocked' : 'detected (monitor mode, request was allowed)';
const blocks = [
  section(`*SQL injection ${outcome}* on \`${esc(alert.host, 100)}\``),
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*Request*\n${esc(alert.method, 10)} ${esc(alert.path, 200)}` },
      { type: 'mrkdwn', text: `*Source IP*\n${esc(alert.ip, 45)}` },
      byRegex
        ? { type: 'mrkdwn', text: `*Detected by*\nregex signature \`${signatureId}\` (no ML call)` }
        : { type: 'mrkdwn', text: `*ML confidence*\n${pct(alert.probability)} (threshold ${pct(alert.threshold)})` },
      { type: 'mrkdwn', text: `*Flagged values*\n${alert.flagged_count ?? values.length}, top: ${esc(alert.source, 80)}` },
    ],
  },
  section(osint),
  ...(values.length ? values.map(valueBlock) : [section('_no values included_')]),
  ...(byRegex
    ? [section(`_Blocked by a WAF signature. If this is a false positive, adjust the \`${signatureId}\` pattern in SIGNATURES in waf_interceptor.lua; the false-positive button only retrains the ML model._`)]
    : []),
  {
    type: 'context',
    elements: [{
      type: 'mrkdwn',
      text: `engine \`${byRegex ? 'regex' : 'ml'}\` | request_id \`${esc(alert.request_id, 40)}\` | ml_request_id \`${esc(alert.ml_request_id ?? '-', 40)}\` | ${esc(alert.ts, 30)}`,
    }],
  },
];

// Blocks go inside an attachment so the message gets a coloured bar, which
// the feedback workflow turns green once a value is flagged as a false positive.
const summary = `SQL injection ${blocked ? 'blocked' : 'detected'} from ${esc(alert.ip, 45)} on ${esc(alert.host, 100)}`;
const message = (text, color) => JSON.stringify({ text, attachments: [{ color, blocks }] });

return [{
  json: {
    ip: alert.ip ?? null,
    request_id: alert.request_id ?? null,
    action: alert.action ?? null,
    probability: alert.probability ?? null,
    abuse_score: abuseScore,
    isp: intel?.isp ?? null,
    country: intel?.countryCode ?? null,
    // Top-level text shows above the attachment and is what notifications use;
    // <!here> must be there (not inside the attachment) to notify.
    slack_high: message(`<!here> :rotating_light: *High-threat source IP* (AbuseIPDB ${abuseScore}%): ${summary}`, RED),
    slack_standard: message(`${blocked ? ':no_entry:' : ':warning:'} ${summary}`, blocked ? RED : AMBER),
  },
}];
